// Watch videos: a fixed, fictional catalogue (like DEMO_QUESTS), shared by the seed, the Watch
// page and Muse's Marketplace picks. Creators are seeded fictional people; no real people, shows
// or brands. Posters are generated by `npm run gen:images` into /seed/videos/<key>.webp.
import raw from './videos.json';

export type SeedVideo = {
  key: string;
  title: string;
  /** Handle of the fictional creator. */
  creator: string;
  minutes: number;
  topics: string[];
  /** Image prompt for gen:images (not shown in the app). */
  poster: string;
};

export const SEED_VIDEOS: readonly SeedVideo[] = raw as SeedVideo[];
export const VIDEO_BY_KEY: ReadonlyMap<string, SeedVideo> = new Map(SEED_VIDEOS.map((v) => [v.key, v]));
export const videoPoster = (key: string) => `/seed/videos/${key}.webp`;

